def deep_type_check(value) -> str:
    if value is None:
        return 'null'
    if isinstance(value, bool):
        return 'boolean'
    if isinstance(value, int) or isinstance(value, float):
        return 'number'
    if isinstance(value, str):
        return 'string'
    if isinstance(value, list):
        return 'array'
    if isinstance(value, dict):
        return 'object'
    if callable(value):
        return 'function'
    return 'unknown'

def validate(data: dict, schema: dict) -> dict:
    errors = []
    for key, expected_type in schema.items():
        if key not in data:
            errors.append(f"{key}: missing field")
        else:
            actual_type = deep_type_check(data[key])
            if actual_type != expected_type:
                errors.append(f"{key}: expected {expected_type} but got {actual_type}")
    return {'valid': len(errors) == 0, 'errors': errors}

def create_validator(schema: dict):
    def validator(data):
        return validate(data, schema)
    return validator

